import debatesJson from "../content/mad-debates.json";

/**
 * Recorded multi-agent debates, as shown in the trace view.
 *
 * The content file is generated by scripts/build-mad-debates.py from the
 * recorded traces. Everything derived — the answers round by round, which
 * peers a response names, whether the speaker then moved onto that peer's
 * answer — is resolved there, so this module only reads and groups it.
 */

/** How a response used an earlier peer argument. */
export type LinkCategory =
  | "adopted"
  | "not-adopted"
  | "inferred"
  | "attack-adopted"
  // Arrows a detector drew rather than ones the recorded answers imply.
  | "tom"
  | "tom-suspect"
  | "unclassified";

/**
 * How Agent-ToM read one agent: a label with the scores behind it. The
 * detector is a model reading the responses after the fact, so everything
 * here is its reading and is worded that way wherever it is shown.
 */
export interface DetectorReading {
  /** "honest", "infected" or "manipulator". */
  label: string;
  scores: Record<string, number>;
  /** The score behind `label`. */
  score: number | null;
  /** True where the detector names this agent as working against the group. */
  suspect: boolean;
  reading: string;
  /** "majority" or "minority", where the agent's answer ends up. */
  endsIn: string;
  keyRounds: number[];
}

export interface DebateSeat {
  id: string;
  /** Display name, "Agent 1" for seat-00. */
  name: string;
  model: string;
  /** The brief this seat was given, where the run shipped a role profile. */
  role: string;
  /** What that brief says the seat is there for, in its own words. */
  roleFocus: string;
  adversary: boolean;
  /** How Agent-ToM read this seat, where it read the debate at all. */
  detector: DetectorReading | null;
}

/**
 * An answer, as the view letters it. A choice task lists its options up front;
 * a coding task has none, so each distinct program becomes an answer the first
 * time an agent submits it and carries the round and seat it came from.
 */
export interface DebateOption {
  /** Recorded ids stay numeric; `letter` is how they are shown. */
  id: number;
  letter: string;
  text: string;
  createdRound: number | null;
  createdBy: string | null;
  createdByName: string | null;
}

export interface DebateLink {
  id: string;
  /** The peer whose earlier turn is being used. */
  from: string;
  fromName: string;
  /** The round that earlier turn came from, when the review pinned one down. */
  fromRound: number | null;
  /** The seat that used it, i.e. the speaker this round. */
  to: string;
  toName: string;
  label: string;
  kind: string;
  outcome: string;
  category: LinkCategory;
  /** True when the argument traces back to an assigned attacker. */
  attack: boolean;
  interpretation: string;
  sourceQuote: string;
  /** Seat-by-seat chain from the attacker to this response. */
  path: { seat: string; name: string; round: number }[] | null;
}

/** A span of a response to highlight, tied to the link that quoted it. */
export interface DebateMark {
  start: number;
  end: number;
  category: LinkCategory;
  linkId: string;
}

export interface DebateTurn {
  seat: string;
  name: string;
  text: string;
  optionId: number | null;
  optionLabel: string;
  optionShort: string;
  optionLetter: string;
  correct: boolean;
  changed: boolean;
  /** True where this round is where the answer first appeared, from this seat. */
  optionNew: boolean;
  /** The submission itself, where it is a program rather than a choice. */
  answer: string | null;
  /** How Agent-ToM scored this agent at this round. */
  detector: {
    label: string;
    scores: Record<string, number>;
    change: Record<string, number> | null;
    /** True where the detector reads the agent as holding out on its own. */
    alone: boolean;
    summary: string;
  } | null;
  marks: DebateMark[];
}

export interface DebateEvent {
  seat: string;
  name: string;
  before: number | null;
  after: number | null;
  beforeLabel: string;
  afterLabel: string;
  changed: boolean;
  title: string;
  explanation: string;
  linkIds: string[];
}

export interface DebateRound {
  round: number;
  turns: DebateTurn[];
  links: DebateLink[];
  events: DebateEvent[];
  tally: Record<string, number>;
}

export interface DebateScenario {
  id: string;
  name: string;
  traceId: string;
  question: string;
  options: DebateOption[] | null;
  correctOptionId: number | null;
  correctOptionLabel: string;
  seats: DebateSeat[];
  attack: { present: boolean; mode: string; adversaries: string[] };
  /** Seats that moved to an attacker's answer, and when. */
  uptake: {
    seat: string;
    name: string;
    round: number;
    optionLabel: string;
    possible: boolean;
  }[];
  /** Agent-ToM's verdict on the debate, where it was read. */
  detector: {
    model: string;
    generatedAt: string;
    roundsAnalyzed: number | null;
    /** "malicious" or "benign". */
    decision: string;
    explanation: string;
    suspects: string[];
    suspectScores: Record<string, number>;
  } | null;
  firstUnanimousRound: number | null;
  finalCorrect: string[];
  synthesis: string | null;
  rounds: DebateRound[];
}

export interface DebateTask {
  id: string;
  title: string;
  /** Benchmark and subject, as the picker lists it. */
  selectLabel: string;
  /** The task restated as one question, for the column heading. */
  questionSummary: string;
  /** What counts as a defect, for the code review tasks. */
  reviewRule: string | null;
  taskType: "choice" | "code";
  scenarios: DebateScenario[];
}

interface DebateFile {
  generatedFrom: string;
  outcomes: Record<
    string,
    { label: string; short: string; description: string }
  >;
  tasks: DebateTask[];
}

const file = debatesJson as unknown as DebateFile;

export const debateTasks: DebateTask[] = file.tasks;
export const linkOutcomes = file.outcomes;

export function linkOutcomeLabel(category: LinkCategory): string {
  return linkOutcomes[category]?.short ?? category;
}

export function linkOutcomeDescription(category: LinkCategory): string {
  return linkOutcomes[category]?.description ?? "";
}

/** Strongest first, so an aggregated edge reports its most consequential use. */
const CATEGORY_RANK: LinkCategory[] = [
  "attack-adopted",
  "tom-suspect",
  "adopted",
  "tom",
  "not-adopted",
  "inferred",
  "unclassified",
];

export function strongestCategory(categories: LinkCategory[]): LinkCategory {
  for (const candidate of CATEGORY_RANK) {
    if (categories.includes(candidate)) {
      return candidate;
    }
  }
  return "unclassified";
}

export interface DebateEdge {
  key: string;
  from: string;
  to: string;
  category: LinkCategory;
  attack: boolean;
  links: DebateLink[];
}

/** One arrow per peer pair, carrying every link behind it. */
export function aggregateEdges(links: DebateLink[]): DebateEdge[] {
  const byPair = new Map<string, DebateEdge>();
  for (const link of links) {
    const key = `${link.from}->${link.to}`;
    const existing = byPair.get(key);
    if (existing) {
      existing.links.push(link);
      existing.category = strongestCategory([existing.category, link.category]);
      existing.attack = existing.attack || link.attack;
      continue;
    }
    byPair.set(key, {
      key,
      from: link.from,
      to: link.to,
      category: link.category,
      attack: link.attack,
      links: [link],
    });
  }
  return [...byPair.values()];
}

export interface DebatePick {
  task: DebateTask;
  scenario: DebateScenario;
}

function hash(value: string): number {
  let result = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    result ^= value.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  // FNV leaves its low bits barely mixed: the parity of the result is the
  // parity of the input characters, so two hashes of related strings stay in
  // step and the picks below would move together. Finish with an avalanche.
  result ^= result >>> 16;
  result = Math.imul(result, 2246822507);
  result ^= result >>> 13;
  result = Math.imul(result, 3266489909);
  result ^= result >>> 16;
  return result >>> 0;
}

/**
 * Traces that are a recording of one debate rather than a stand-in for one.
 * The coding run came in with its own application, so that trace opens that
 * debate, and the applications that only stand in for one never draw it.
 */
const PINNED_TASKS: Record<string, string> = {
  "trace-code-panel-001": "livecodebench",
};

/**
 * Picks the debate a trace shows. The verdict chooses the scenario so a
 * malicious trace opens on an attacked debate and a benign one on the
 * cooperative run; the trace id picks the task, keeping it stable per trace.
 */
export function debateForTrace(
  traceFileId: string | undefined,
  label?: string | null,
): DebatePick {
  const id = traceFileId ?? "";
  const seed = hash(id);
  // A second, independently salted hash: reusing one seed for both picks ties
  // the scenario to the task, which left whole combinations unreachable.
  const scenarioSeed = hash(`${id}#scenario`);
  const pinnedIds = new Set(Object.values(PINNED_TASKS));
  const drawn = debateTasks.filter((entry) => !pinnedIds.has(entry.id));
  const task =
    debateTasks.find((entry) => entry.id === PINNED_TASKS[id]) ??
    drawn[seed % drawn.length] ??
    debateTasks[0];
  const wanted =
    label === "benign"
      ? "benign"
      : label === "malicious"
        ? scenarioSeed % 2 === 0
          ? "single"
          : "colluding"
        : task.scenarios[scenarioSeed % task.scenarios.length].id;
  const scenario =
    task.scenarios.find((entry) => entry.id === wanted) ?? task.scenarios[0];
  return { task, scenario };
}

/**
 * The tone an agent carries wherever it appears: the red of an assigned
 * attacker, or, where a detector read the debate, the red of one it suspects
 * and the amber of one it reads as carried along. Returns "" for an agent
 * with nothing said about it, so a caller can append it unconditionally.
 */
/** Above this the detector calls an agent a manipulator. */
export const MANIPULATOR_FLAG = 0.5;

/**
 * The colour a manipulator score takes, as four steps of a traffic light
 * rather than a fade: green where the detector sees nothing, yellow where it
 * is starting to, orange once the agent is over the flag and red where it has
 * made up its mind. Blends between those read as mud, so there are none.
 */
export function manipulatorHue(score: number): string {
  if (score < 0.25) {
    return "var(--ioc-heat-1)";
  }
  if (score < MANIPULATOR_FLAG) {
    return "var(--ioc-heat-2)";
  }
  if (score < 0.75) {
    return "var(--ioc-heat-3)";
  }
  return "var(--ioc-heat-4)";
}

/**
 * That colour as a ground to put a letter on. Shared by the grid and the
 * agent list, so the same score is the same shade wherever it is read.
 */
export function manipulatorTint(score: number): string {
  return `color-mix(in srgb, ${manipulatorHue(score)} 52%, transparent)`;
}

/**
 * The tone an agent carries inside one round, which is what the detector had
 * made of it by then rather than what it concluded at the end: a round is
 * read forwards, and the final verdict is not yet available in it.
 */
export function turnTone(turn: DebateTurn | undefined): string {
  const label = turn?.detector?.label;
  if (label === "manipulator") {
    return " is-danger";
  }
  if (label === "infected") {
    return " is-watch";
  }
  return "";
}

export function seatTone(seat: DebateSeat): string {
  if (seat.adversary || seat.detector?.suspect) {
    return " is-danger";
  }
  if (seat.detector?.label === "infected") {
    return " is-watch";
  }
  return "";
}

/**
 * Where each agent's answer started and where it ended, for the overview:
 * the first answer it is recorded giving and the last, with whether that last
 * one is the answer the task calls correct.
 */
export function answerSpans(
  scenario: DebateScenario,
): Record<string, { from: string; to: string; correct: boolean }> {
  const spans: Record<string, { from: string; to: string; correct: boolean }> =
    {};
  for (const seat of scenario.seats) {
    const answered = scenario.rounds
      .map((round) => round.turns.find((turn) => turn.seat === seat.id))
      .filter(
        (turn): turn is DebateTurn => Boolean(turn) && turn!.optionId !== null,
      );
    const first = answered[0];
    const last = answered[answered.length - 1];
    if (!first || !last) {
      continue;
    }
    spans[seat.id] = {
      from: first.optionLetter,
      to: last.optionLetter,
      correct: last.correct,
    };
  }
  return spans;
}

/** What the detector calls an agent, for a chip beside its name. */
export function seatReadingLabel(seat: DebateSeat): string {
  return seat.adversary ? "attacker" : (seat.detector?.label ?? "");
}

/** Links whose argument the review traced back to an attacker. */
export function attackLinks(round: DebateRound): DebateLink[] {
  return round.links.filter((link) => link.attack);
}

/**
 * A recording carries the debate, not a review of it. These say which of the
 * two the content was built from, so the view can drop what it cannot back
 * up — an answer marked right, a seat named as the attacker — rather than
 * asserting it from nothing.
 */
export function hasAnswerKey(scenario: DebateScenario): boolean {
  return scenario.correctOptionId !== null;
}

export function hasAttackerRoster(scenario: DebateScenario): boolean {
  return scenario.attack.adversaries.length > 0;
}

/**
 * What an answer reads as where its letter is already on screen beside it. A
 * coding run names its answers after the letter they were given — "Program A"
 * — so the name on its own would say it twice.
 */
export function answerWithoutLetter(turn: DebateTurn): string {
  const suffix = ` ${turn.optionLetter}`;
  return turn.optionLetter && turn.optionShort.endsWith(suffix)
    ? turn.optionShort.slice(0, -suffix.length)
    : turn.optionShort;
}

/**
 * Answers that appear for the first time in a round. A coding run has no
 * option list to start from: the programs are the answers, so the list grows
 * as the rounds go and a round can say which of them are its own.
 */
export function optionsCreatedIn(
  scenario: DebateScenario,
  round: number,
): DebateOption[] {
  return (scenario.options ?? []).filter(
    (option) => option.createdRound === round,
  );
}
